"use client"

import BiryaniLegendsTemplate, { BL_LEGENDS } from "@/components/ui/biryani-legends-template"

// The real-asset edition: three generated pot photographs cut out to transparency,
// three public-domain engravings turned into ink on a transparent ground, and a
// generated laid-paper tile. Embedded as data: URIs so the demo makes no request
// (21st's capture refuses off-origin images, and rejects demo files over 200 KB).
// Full-size files and their origins: media/biryani-legends-template/ASSETS.md.
const FAIZA =
  "data:image/avif;base64,"
const SELVARAJAN =
  "data:image/avif;base64,"
const SONIA =
  "data:image/avif;base64,"
const TELLICHERRY =
  "data:image/avif;base64,"
const AMBUR =
  "data:image/avif;base64,"
const LUCKNOW =
  "data:image/avif;base64,"
const PAPER =
  "data:image/webp;base64,"

const PLATES = [
  { src: TELLICHERRY, aspect: 2.6, alt: "Engraving of the harbour at Tellicherry, East Indiamen at anchor before the fort" },
  { src: AMBUR, aspect: 1.85, alt: "Engraving of the hill fort at Ambur above the plain" },
  { src: LUCKNOW, aspect: 1.4, alt: "Engraving of the mosque of the Great Imambara at Lucknow across its garden" },
]
const POTS = [FAIZA, SELVARAJAN, SONIA]

const legends = BL_LEGENDS.map((l, i) => ({ ...l, dish: { ...l.dish, src: POTS[i] }, engravingImage: PLATES[i] }))

export default function DemoPhotos() {
  // w-full matters: 21st centres demos in a flex wrapper.
  return (
    <div className="w-full">
      <BiryaniLegendsTemplate legends={legends} paperTexture={PAPER} />
    </div>
  )
}
